using System;

public class ExcellentStudent
{
    private string name;
    private double average;
    private bool davidsonLovesYou;

    public double GetAverage() { return average; }   // «لكل خاصية عملية Get» (as the book says)

    public ExcellentStudent(string name, double average, bool davidsonLovesYou)
    {
        this.name = name;
        this.average = average;
        this.davidsonLovesYou = davidsonLovesYou;
    }

    public void RaisingStudentsAverageGrades()
    {
        average = Math.Min(100, average * 1.1);
    }

    public int Compare(ExcellentStudent other)
    {
        if (davidsonLovesYou && !other.davidsonLovesYou) return 1;
        if (!davidsonLovesYou && other.davidsonLovesYou) return -1;
        if (average > other.average) return 1;
        if (average < other.average) return -1;
        return 0;
    }
}

public class Program
{
    public static void Main()
    {
        ExcellentStudent a = new ExcellentStudent(Console.ReadLine(), double.Parse(Console.ReadLine()), bool.Parse(Console.ReadLine()));
        ExcellentStudent b = new ExcellentStudent(Console.ReadLine(), double.Parse(Console.ReadLine()), bool.Parse(Console.ReadLine()));
        Console.WriteLine(a.Compare(b));
        a.RaisingStudentsAverageGrades();
        Console.WriteLine(Math.Round(a.GetAverage(), 2));
        Console.WriteLine(a.Compare(b));
    }
}

