using System;

public class Font
{
    private string name;
    private int size;
    private bool bold;
    private bool underline;

    public Font(string name, int size, bool bold, bool underline)
    {
        this.name = name;
        this.size = size;
        this.bold = bold;
        this.underline = underline;
    }

    public int GetSize() { return size; }
    public bool IsBold() { return bold; }
    public bool IsUnderline() { return underline; }

    public Font(string name, int size)
    {
        this.name = name;
        this.size = size;
        bold = false;
        underline = false;
    }

    public void Increase()
    {
        size++;
    }

    public void Decrease()
    {
        size--;
    }

    public void ToggleUnderline()
    {
        underline = !underline;
    }
}

public class Program
{
    public static void Main()
    {
        Font f = new Font(Console.ReadLine(), int.Parse(Console.ReadLine()));
        foreach (char op in Console.ReadLine())
        {
            if (op == 'I') f.Increase();
            else if (op == 'D') f.Decrease();
            else if (op == 'U') f.ToggleUnderline();
        }
        Console.WriteLine(f.GetSize());
        Console.WriteLine(f.IsUnderline());
        Console.WriteLine(f.IsBold());
    }
}
